import {cents} from './business.js?v=20261101-v5b';
export function parseMoney(value){let v=String(value??'').trim().replace(/R\$|\s/g,'');let neg=/^\(.*\)$/.test(v);v=v.replace(/[()]/g,'');if(!/^[+-]?[\d.,]+$/.test(v))throw Error('Valor monetário inválido: '+String(value).slice(0,30));const comma=v.lastIndexOf(','),dot=v.lastIndexOf('.');if(comma>=0&&dot>=0){const dec=comma>dot?',':'.';v=v.replace(dec===','?/\./g:/,/g,'').replace(',','.')}else if(comma>=0)v=v.replace(',','.');else if(dot>=0&&/^[-+]?\d{1,3}(\.\d{3})+$/.test(v))v=v.replace(/\./g,'');const n=Number(v)*(neg?-1:1);if(!Number.isFinite(n)||Math.abs(n)>9999999999||Math.abs(n*100-Math.round(n*100))>.0001)throw Error('Valor monetário inválido ou com mais de duas casas decimais');return cents(n)/100}
export function parseDate(value){const v=String(value??'').trim();let y,m,d,match;if((match=v.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ T].*)?$/))){[,y,m,d]=match}else if((match=v.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/))){[,d,m,y]=match}else if((match=v.match(/^(\d{4})(\d{2})(\d{2})(?:\d{6}(?:\.\d+)?(?:\[.*\])?)?$/))){[,y,m,d]=match}else throw Error('Data inválida: '+v.slice(0,30));const dt=new Date(Date.UTC(+y,+m-1,+d));if(dt.getUTCFullYear()!==+y||dt.getUTCMonth()!==+m-1||dt.getUTCDate()!==+d)throw Error('Data inexistente: '+v);return `${y}-${m}-${d}`}
export function readCSV(text,separator=';'){if(separator==='tab')separator='\t';if(![';',',','\t'].includes(separator))throw Error('Separador inválido');const rows=[];let row=[],cell='',quoted=false;const v=text.replace(/^\uFEFF/,'');for(let i=0;i<v.length;i++){const c=v[i];if(c==='"'){if(quoted&&v[i+1]==='"'){cell+='"';i++}else if(quoted||cell.length===0)quoted=!quoted;else cell+=c}else if(c===separator&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&v[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('O CSV possui aspas sem fechamento');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
const stableHash=s=>{let a=2166136261,b=5381;for(const c of s){a=Math.imul(a^c.charCodeAt(0),16777619);b=Math.imul(b,33)^c.charCodeAt(0)}return (a>>>0).toString(16)+(b>>>0).toString(16)};
export function parseStatement(text,name,options={}){const errors=[],lines=[],seen=new Map();let raw=[];
 if(/\.ofx$/i.test(name)||/<OFX[>\s]/i.test(text)){const blocks=[...text.matchAll(/<STMTTRN>([\s\S]*?)(?:<\/STMTTRN>|(?=<STMTTRN>|<\/BANKTRANLIST>))/gi)];if(!blocks.length)throw Error('Nenhuma movimentação OFX encontrada');const tag=(b,k)=>(b.match(new RegExp('<'+k+'>([^<\\r\\n]+)','i'))||[])[1]?.trim()||'';raw=blocks.map(m=>({date:tag(m[1],'DTPOSTED'),description:[tag(m[1],'NAME'),tag(m[1],'MEMO')].filter(Boolean).join(' · ')||tag(m[1],'TRNTYPE'),amount:String(Number(tag(m[1],'TRNAMT'))),id:tag(m[1],'FITID')}));
 }else{const rows=readCSV(text,options.csv_separator||';');const start=options.csv_header===false?0:1;raw=rows.slice(start).map((r,i)=>({date:r[Number(options.csv_date??0)],description:r[Number(options.csv_description??1)],amount:r[Number(options.csv_amount??2)],id:Number(options.csv_id??-1)>=0?r[Number(options.csv_id)]:null,line:i+start+1}))}
 for(let i=0;i<raw.length;i++){try{const r=raw[i],date=parseDate(r.date),amount=parseMoney(r.amount),description=String(r.description||'').trim();if(!description)throw Error('Descrição vazia');if(!amount)continue;const base=date+'|'+cents(amount)+'|'+description.normalize('NFKC').replace(/\s+/g,' ').toLowerCase();const occurrence=(seen.get(base)||0)+1;seen.set(base,occurrence);lines.push({date,description,amount,external_id:r.id?'bank:'+String(r.id).slice(0,280):'csv:'+stableHash(base)+':'+occurrence})}catch(e){errors.push({line:raw[i].line||i+1,message:e.message})}}
 if(lines.length>5000)throw Error('Divida o extrato em arquivos de até 5.000 movimentações');return {lines,errors,income:lines.filter(l=>l.amount>0).reduce((n,l)=>n+l.amount,0),expense:lines.filter(l=>l.amount<0).reduce((n,l)=>n-l.amount,0)};
}
